    if(!this.state.watchlist.length)this.state.watchlist=DEFAULT.watchlist;
    this.forceDemo=new URLSearchParams(location.search).has('demo')||document.documentElement.dataset.mode==='demo';this.kind='demo';this.feedState='connecting';this.panel='overview';this.depthTab='book';this.history=new UndoStack();this.compute=new ComputeClient();this.cache=new CandleCache();this.market=new MarketData();this.demoQuotes=new Map();this.modeLabel='Synthetic preview';this.loadId=0;this.indicatorId=0;this.alerts=new AlertEngine(this.readAlerts());this.broker=this.readBroker();this.paperSide='buy';this.comparisonSymbol='ETH-USD';this.compareLoad=0;this.comparison=null;this.replaying=false;this.replayTimer=null;this.book=null;this.tradesSeen=new Set();this.currentHover=null;this.computationBusy=false;this.computationAgain=false;this.panelDirty=false;this.lastMetrics=0;this.products=[...PRODUCTS];
    hydrateIcons();$('drawing-tools').innerHTML=tools.map(([tool,title])=>`<button class="tool-button ${tool==='cursor'?'active':''}" data-tool="${tool}" title="${title}" aria-label="${title}">${icon(tool)}</button>`).join('');
    this.chart=new Chart($('primary-chart'),{symbol:this.state.symbol,interval:this.state.interval,
      onHover:(b,i)=>this.hover(b,i),onView:v=>{if(this.comparison)this.comparison.syncView(v);},onCrosshair:t=>{if(this.comparison){this.comparison.linkedTime=t;this.comparison.invalidate(false);}},
      onNeedMore:()=>this.loadMore(),onMode:mode=>{$('renderer-label').textContent=mode;},onFrame:m=>this.metrics(m),onTool:tool=>this.syncTools(tool),onDrawings:(before,after)=>this.drawingChanged(before,after),
      onSelect:()=>{if(this.depthTab==='drawings')this.renderDepth();},onContext:position=>this.chartMenu(position),sourceLabel:()=>this.exportLabel()});
    this.applyState();this.installEvents();this.installFeed();this.renderWatchlist();this.renderPanel();this.updateIdentity();this.setTheme(this.state.theme,false);
    this.clock=setInterval(()=>this.updateClock(),1000);this.updateClock();this.health=setInterval(()=>this.refreshHealth(),3000);this.autosave=setInterval(()=>this.save(false),20000);
    this.start();if(!this.forceDemo)this.market.connect(this.feedSymbols());else this.setFeedStatus({state:'demo',text:'Offline demo · synthetic data'});
