  async start(){
    const meta=read('aureon.import',null);
    if(meta&&!this.forceDemo&&meta.symbol===this.state.symbol){
      const cached=await this.cache.get('workspace-import');
      if(cached?.bars?.length&&cached.symbol===meta.symbol){
        const viewInterval=this.state.interval;await this.installImported(this.state,normalizeCandles(cached.bars),cached.interval,cached.source);
        if(viewInterval!==cached.interval)this.changeInterval(viewInterval);return;
      }
    }
    this.loadSymbol(this.state.symbol,this.state.interval);
  }
  readAlerts(){const a=read('aureon.alerts',[]);return Array.isArray(a)?a.filter(x=>x&&typeof x.symbol==='string'&&Number.isFinite(x.price)&&typeof x.active==='boolean'&&typeof x.id==='string'&&Number.isFinite(x.created)&&(!x.triggered||Number.isFinite(x.triggered))).slice(0,500):[];}
  readBroker(){try{const s=read('aureon.paper',null);if(s&&Number.isFinite(s.cash)&&s.cash>=0&&Number.isFinite(s.initial)&&s.initial>0&&s.positions&&Array.isArray(s.orders)&&Array.isArray(s.fills)&&Number.isFinite(s.feeBps)&&s.feeBps>=0&&s.feeBps<=1000){for(const p of Object.values(s.positions))if(![p.qty,p.cost,p.realized].every(Number.isFinite)||p.qty<0||p.cost<0)throw new Error();return new PaperBroker(s);}}catch{}return new PaperBroker();}
  applyState(){Object.assign(this.chart,{symbol:this.state.symbol,interval:this.state.interval,style:this.state.style,scale:this.state.scale,theme:this.state.theme,enabled:[...this.state.indicators],drawings:this.state.drawings[this.state.symbol]||[]});this.chart.invalidate();this.syncToolbar();}
