      const cached=await this.cache.get(`${symbol}:${interval}`);if(id!==this.loadId)return;
      if(cached?.bars?.length){this.kind='cache';this.modeLabel='Cached Coinbase history';this.series=new CandleSeries(cached.bars,interval);this.chart.setData(this.series.bars,{}, {reset:true});this.refreshIndicators();this.setSource();this.updateAllUI();}
      const result=await this.market.history(symbol,interval,{signal});if(id!==this.loadId)return;if(!result.bars.length)throw new Error('No candles returned for this symbol.');
      this.kind='market';this.modeLabel='Coinbase Exchange';this.series=new CandleSeries(result.bars,interval);this.series.acceptAfter=result.cutoff;this.chart.setData(this.series.bars,{}, {reset:true});this.refreshIndicators();this.cache.put(`${symbol}:${interval}`,{bars:result.bars,source:result.source});this.setSource();this.updateAllUI();this.loadBook();
