  queueTick(){if(this.tickTimer)return;this.tickTimer=setTimeout(()=>{this.tickTimer=null;this.chart.setData(this.series.bars);this.refreshIndicators();this.hover(this.visibleBars().at(-1),this.visibleBars().length-1);this.updateBarCount();},100);}
