  visibleBars(){return this.replaying?this.series.bars.slice(0,this.chart.endLimit):this.series?.bars||[];}
  hover(bar,index){if(!bar)return;this.currentHover={bar,index};const up=bar.c>=bar.o,css=up?'positive':'negative';$('ohlc-line').innerHTML=[['O',bar.o],['H',bar.h],['L',bar.l],['C',bar.c]].map(([k,v])=>`<span>${k}<b class="${css}">${formatPrice(v)}</b></span>`).join('')+`<span class="${css}">${signed((bar.c/bar.o-1)*100)}%</span>`;
    if(this.indicatorData)this.renderIndicatorLegend(index);if(this.panel==='data'){clearTimeout(this.hoverTimer);this.hoverTimer=setTimeout(()=>this.renderPanel(),40);}}
