  quote(symbol){if(this.kind==='demo')return this.demoQuotes.get(symbol);if(symbol===this.state.symbol&&(this.kind==='import'||this.kind==='cache'))return this.previewQuote(symbol,this.visibleBars());return this.market.quotes.get(symbol)||(symbol===this.state.symbol?this.previewQuote(symbol,this.visibleBars()):null);}
